// Saves the home page's "Our Signature Scents" perfumes (and their photos) into the site
// itself, so the section shows instantly even while the API is asleep on Render.
// Writes js/featured-snapshot.js and images/featured/*. Output only changes when the
// featured perfumes change, so the workflow commits only when there is something new.
import { mkdir, rm, writeFile } from 'node:fs/promises';

const API = 'https://abs-fragrances.onrender.com/api';
const IMG_DIR = 'images/featured';
const EXT = { 'image/webp': 'webp', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/avif': 'avif', 'image/gif': 'gif' };

async function get(path) {
  for (let i = 0; ; i++) {
    try {
      const r = await fetch(API + path, { signal: AbortSignal.timeout(90000) });
      if (!r.ok) throw new Error(`${path} → ${r.status}`);
      return r;
    } catch (err) {
      if (i >= 3) throw err;
      await new Promise(res => setTimeout(res, 15000)); // server may still be waking up
    }
  }
}

const brands = (await (await get('/products/brands')).json()).brands || [];
const featured = ((await (await get('/products')).json()).products || []).filter(p => p.is_featured);
if (!featured.length) { console.log('No featured perfumes returned — leaving the snapshot as it is.'); process.exit(0); }

await rm(IMG_DIR, { recursive: true, force: true });
await mkdir(IMG_DIR, { recursive: true });

const products = [];
for (const p of featured) {
  const row = { ...p };
  delete row.full_desc; // not shown on the card; the live data fills it in for the details popup
  if (p.image_url) {
    try {
      const r = await fetch(p.image_url, { signal: AbortSignal.timeout(60000) });
      const ext = EXT[(r.headers.get('content-type') || '').split(';')[0]];
      if (!r.ok || !ext) throw new Error(`status ${r.status}`);
      // The photo's version is in the file name: images/ is cached by browsers for a week,
      // so a changed photo must get a new name to show up.
      const v = new URL(p.image_url).searchParams.get('v') || '';
      const file = `${IMG_DIR}/${p.id.replace(/[^\w-]/g, '_')}-${v.slice(0, 8)}.${ext}`;
      await writeFile(file, Buffer.from(await r.arrayBuffer()));
      row.image_url = file;
      row.image_v = v; // lets the page keep this copy while the live photo is the same
    } catch (err) {
      console.warn(`Photo for ${p.id} not saved (${err.message}); keeping the API link.`);
    }
  }
  products.push(row);
}

const used = new Set(products.map(p => p.brand_id));
const data = { brands: brands.filter(b => used.has(b.id)), products };
await writeFile('js/featured-snapshot.js',
  '// Generated by .github/scripts/build-featured-snapshot.mjs — do not edit by hand.\n' +
  `window.FEATURED_SNAPSHOT = ${JSON.stringify(data)};\n`);
console.log(`Saved ${products.length} featured perfumes.`);
